WITH enriched AS (SELECT id, shipped_date, status, NTILE(3) OVER (PARTITION BY order_id ORDER BY cost, id) AS cost_bucket, AVG(cost) OVER (PARTITION BY carrier, order_id ORDER BY shipped_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS cost_avg_3_prior FROM shipments) SELECT DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, DATE_TRUNC('YEAR', shipped_date) AS year_start, CASE WHEN cost_bucket >= 9 THEN 'HIGH' ELSE 'LOW' END AS cost_bucket_tier, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, SUM(cost_avg_3_prior) FILTER (WHERE status = 'DELIVERED') AS delivered_total_cost_avg_3_prior, COUNT(*) AS num_rows, ROUND(SUM(cost_bucket) / NULLIF(COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END), 0), 2) AS cost_bucket_per_delivered, COUNT(CASE WHEN status = 'LOST' THEN 1 END) AS lost_count, SORT_ARRAY(COLLECT_SET(status)) AS status_list, GROUPING_ID() AS grouping_id FROM enriched GROUP BY ROLLUP (DATE_TRUNC('QUARTER', shipped_date), DATE_TRUNC('YEAR', shipped_date), CASE WHEN cost_bucket >= 9 THEN 'HIGH' ELSE 'LOW' END) HAVING cost_bucket_per_delivered < 1000000;
